// authModeClient is the single AuthMode value excluded from the async queue
// (D-Q1): CLIENT sources need user credentials and are Mode-B-only. Empty/local
// (tv-parser) and SERVER are server-runnable and therefore queued.
const authModeClient = "CLIENT"

// §4.4 zero-value defaults. A zero QueueConfig is filled to these by NewQueue.
const (
	defaultWorkers       = 4
	defaultMaxAttempts   = 3
	defaultLeaseTTL      = 60 * time.Second
	defaultBackoff       = 2 * time.Second
	defaultExhaustedCool = 7 * 24 * time.Hour
	defaultNoDataCool    = 30 * 24 * time.Hour
	defaultCoolCap       = 365 * 24 * time.Hour
)

// deriveBatch is the pagination width for derivation's QueryItems scan.
const deriveBatch = 1000

// QueueConfig tunes the async queue. Every field has a §4.4 zero-value default
// applied by NewQueue, so a literal QueueConfig{} is a valid, production-default
// configuration; cmd/mellifera overrides fields from MELLIFERA_ENRICH_* env.
type QueueConfig struct {
	Workers       int           // worker-pool size (default 4)
	MaxAttempts   int           // in-memory retries per source before terminal (default 3)
	LeaseTTL      time.Duration // lazy-expiry lease lifetime (default 60s)
	Backoff       time.Duration // initial exponential-backoff step (default 2s)
	ExhaustedCool time.Duration // terminal 'exhausted' cooldown (default 7d, doubling)
	NoDataCool    time.Duration // terminal 'no_data' cooldown (default 30d, flat)
	CoolCap       time.Duration // doubling cap (default 365d)
}

// withDefaults returns cfg with every zero field replaced by its §4.4 default.
// A non-zero caller value is preserved (the env override wins).
func withDefaults(cfg QueueConfig) QueueConfig {
	if cfg.Workers <= 0 {
		cfg.Workers = defaultWorkers
	}
	if cfg.MaxAttempts <= 0 {
		cfg.MaxAttempts = defaultMaxAttempts
	}
	if cfg.LeaseTTL <= 0 {
		cfg.LeaseTTL = defaultLeaseTTL
	}
	if cfg.Backoff <= 0 {
		cfg.Backoff = defaultBackoff
	}
	if cfg.ExhaustedCool <= 0 {
		cfg.ExhaustedCool = defaultExhaustedCool
	}
	if cfg.NoDataCool <= 0 {
		cfg.NoDataCool = defaultNoDataCool
	}
	if cfg.CoolCap <= 0 {
		cfg.CoolCap = defaultCoolCap
	}
	return cfg
}

// Stats is an observability snapshot of the queue (arch §4.4 / AC-2). Counters
// are best-effort and race the worker pool; they are for liveness, not billing.
type Stats struct {
	Pending  int // derived tasks not yet taken by a worker
	InFlight int // items a worker has leased and is processing
	Done     int // items a worker has settled to ready (cumulative)
	Failed   int // items a worker has hard-failed via ctx cancel (cumulative)
}

// Queue is the in-process async enrichment dispatcher (arch §4.4). It DERIVES
// pending (row, plugin) work from items AND series rows + the document
// namespaces + the enrichment_failures ledger (there is NO queue/claim/lease
// table — INV-derived-not-stored), feeds a bounded channel, and a worker pool
// drains it under per-row leases (one per row id; serials-library D5). Row ids
// never collide across the two stores (opaque itm_/ser_ prefixes). Single-
// instance MVP: leases are in-memory and vanish on restart; pending work is
// re-derived from the rows on the next Start.
type Queue struct {
	deps    Deps
	cfg     QueueConfig
	resolve metadataResolver // = deps.Plugins.MetadataSource; tests override

	leases *leaseMap

	libs   map[int64]struct{} // known libraries (registered via Notify)
	libsMu sync.Mutex

	work chan laneTask // bounded buffer of dispatch tasks; closed by Stop

	wg       sync.WaitGroup // worker goroutines
	feederWG sync.WaitGroup // active derive-and-feed goroutines
	cancel   context.CancelFunc
	writeMu  sync.Mutex // serializes store writes (see storeWrite)
	sendMu   sync.Mutex // serializes channel sends (EnqueuePack) against Stop's close

	statPending  atomic.Int64
	statInFlight atomic.Int64
	statDone     atomic.Int64
	statFailed   atomic.Int64

	running atomic.Bool
}

// errAlreadyStarted guards the Start precondition ("not already started"). Start
// is re-entrant across Stop: Stop resets the running flag so Start can launch a
// fresh pool (restart-resume, AC-ledger(c)).
var errAlreadyStarted = errors.New("enrich: queue already started")

// NewQueue constructs a dispatcher over the Phase A collaborators (Deps is
// reused from enrich.go). It fills zero-valued cfg fields with §4.4 defaults and
// returns a Queue that is NOT yet running (no goroutines). The metadata resolver
// is deps.Plugins.MetadataSource; in-package tests override Queue.resolve after
// construction (the metadataResolver seam, R8).
func NewQueue(deps Deps, cfg QueueConfig) *Queue {
	q := &Queue{
		deps:   deps,
		cfg:    withDefaults(cfg),
		leases: newLeaseMap(),
		libs:   make(map[int64]struct{}),
	}
	if deps.Plugins != nil {
		q.resolve = deps.Plugins.MetadataSource
	}
	return q
}

// Start launches the worker pool and (re)derives pending work across every known
// library, feeding the channel. It returns errAlreadyStarted if the pool is
// already running. On ctx.Done() / Stop workers exit cleanly: in-flight leases
// are released (or expire lazily) and pending work survives in items, to be
// re-derived on the next Start. Start is safe to call again after Stop.
func (q *Queue) Start(ctx context.Context) error {
	if !q.running.CompareAndSwap(false, true) {
		return errAlreadyStarted
	}
	q.work = make(chan laneTask, q.cfg.Workers*4) // bounded buffer: backpressure on slow drains
	ctx, q.cancel = context.WithCancel(ctx)
	q.leases = newLeaseMap()
	for i := 0; i < q.cfg.Workers; i++ {
		q.wg.Add(1)
		go q.worker(ctx)
	}
	q.deriveAsync(ctx, q.knownLibs()) // initial sweep across all known libraries
	return nil
}

// Notify signals that a scan persisted new/changed items for a library: it
// registers the library and (re)derives its pending set into the channel. Called
// by scan after it persists items pending (replaces the Phase A inline enrich
// call). Idempotent: done pairs and in-cooldown pairs are not re-added
// (derivation's predicate skips them), so a re-Notify is a no-op extra sweep.
func (q *Queue) Notify(ctx context.Context, libraryID int64) {
	q.registerLib(libraryID)
	q.deriveAsync(ctx, []int64{libraryID})
}

// Stop drains and stops the pool and releases in-memory leases. No worker
// goroutines remain afterward. The known-library registry is preserved so a
// subsequent Start re-derives the same libraries; in-memory queue state and
// leases are discarded (pending work survives in items + ledger).
func (q *Queue) Stop() {
	if !q.running.CompareAndSwap(true, false) {
		return
	}
	if q.cancel != nil {
		q.cancel() // halt feeders (they select on ctx.Done); workers hard-abort current item
	}
	q.feederWG.Wait() // no feeder writes after this point
	q.sendMu.Lock()   // no EnqueuePack send can race the close
	close(q.work)     // workers drain remaining buffered items, then range ends
	q.sendMu.Unlock()
	q.wg.Wait()
	q.cancel = nil
}

// Stats returns a best-effort liveness snapshot (AC-2).
func (q *Queue) Stats() Stats {
	return Stats{
		Pending:  int(q.statPending.Load()),
		InFlight: int(q.statInFlight.Load()),
		Done:     int(q.statDone.Load()),
		Failed:   int(q.statFailed.Load()),
	}
}

// registerLib records a known library (Start sweeps the known set).
func (q *Queue) registerLib(libraryID int64) {
	q.libsMu.Lock()
	q.libs[libraryID] = struct{}{}
	q.libsMu.Unlock()
}

// knownLibs returns a snapshot of the known-library set under the lock.
func (q *Queue) knownLibs() []int64 {
	q.libsMu.Lock()
	out := make([]int64, 0, len(q.libs))
	for id := range q.libs {
		out = append(out, id)
	}
	q.libsMu.Unlock()
	return out
}

// deriveAsync launches a derive-and-feed goroutine for the given libraries. It
// is the only producer into q.work; the feederWG lets Stop wait for producers to
// observe ctx.Done() before closing the channel (preventing send-on-closed).
func (q *Queue) deriveAsync(ctx context.Context, libs []int64) {
	if len(libs) == 0 {
		return
	}
	q.feederWG.Add(1)
	go func() {
		defer q.feederWG.Done()
		q.feed(ctx, libs)
	}()
}

// feed derives the pending (row, plugin) tasks for each library and feeds the
// unique row-id set into the channel. It is the §4.4 derivation producer; the
// worker pool consumes row-by-row under per-row leases. Feeding blocks on the
// bounded channel (backpressure); ctx.Done() aborts the feed promptly.
func (q *Queue) feed(ctx context.Context, libs []int64) {
	for _, lib := range libs {
		tasks, err := q.deriveLibrary(ctx, lib)
		if err != nil {
			continue
		}
		for _, itemID := range uniqueItems(tasks) {
			select {
			case <-ctx.Done():
				return
			case q.work <- laneTask{rowID: itemID}:
				q.statPending.Add(1)
			}
		}
	}
}

// uniqueItems returns the deduplicated row-id set from a task list (a lease is
// per row, so a row with several pending sources is dispatched once and its
// chain drains them serially). It preserves first-seen order.
func uniqueItems(tasks []queueTask) []string {
	seen := make(map[string]struct{}, len(tasks))
	out := make([]string, 0, len(tasks))
	for _, t := range tasks {
		if _, ok := seen[t.rowID]; ok {
			continue
		}
		seen[t.rowID] = struct{}{}
		out = append(out, t.rowID)
	}
	return out
}

// worker is one pool goroutine. It ranges over the channel, routing each task
// to its lane's driver — the metadata dispatch (workItem) or the streams lane
// (workStreams) — until Stop closes the channel. The driver honors ctx
// per-source (a cancelled ctx hard-aborts the in-flight row to failed, then
// the loop continues draining remaining buffered rows before the close ends
// the range).
func (q *Queue) worker(ctx context.Context) {
	defer q.wg.Done()
	for t := range q.work {
		if t.streams {
			q.workStreams(ctx, t.rowID)
			continue
		}
		q.workItem(ctx, t.rowID)
	}
}

// queueTask is one derived (row, plugin) pending unit — row being an item OR a
// series row (serials-library D5; row ids never collide across the stores). The
// dispatch groups by row (per-row lease); pluginID is retained for the
// derivation predicate's test surface (the D-Q1 / cooldown / namespace
// assertions assert the task set).
type queueTask struct {
	rowID, pluginID string
}

// task is an alias preserving the derivation's (row, plugin) vocabulary.
type task = queueTask

// deriveLibrary computes the pending (row, plugin) set for one library per the
// §4.4 derivation predicate (B8) applied IDENTICALLY to both stores
// (serials-library D5): row EXISTS, source applicable + Enabled + AuthMode !=
// CLIENT (D-Q1), namespace ABSENT (not done), NOT in-ledger-cooldown. It reads
// items and series rows (all statuses; the predicate filters) + the ledger; it
// never touches a queue table (INV-derived-not-stored). Parameterized SQL only.
func (q *Queue) deriveLibrary(ctx context.Context, libraryID int64) ([]queueTask, error) {
	items, err := q.allItems(ctx, libraryID)
	if err != nil {
		return nil, err
	}
	seriesRows, err := q.allSeries(ctx, libraryID)
	if err != nil {
		return nil, err
	}
	idx, err := q.fetchFailureIndex(ctx)
	if err != nil {
		return nil, err
	}
	nowt := now()
	tasks := make([]queueTask, 0)
	for _, it := range items {
		mod, err := q.deps.Modules.Get(it.ModuleID)
		if err != nil {
			continue // module unresolvable -> row not derivable (soft)
		}
		for _, pluginID := range pendingSources(mod, decodeDoc(it.Document), it.ID, idx, nowt) {
			tasks = append(tasks, queueTask{rowID: it.ID, pluginID: pluginID})
		}
	}
	for _, sr := range seriesRows {
		mod, err := q.deps.Modules.Get(sr.ModuleID)
		if err != nil {
			continue // module unresolvable -> row not derivable (soft)
		}
		for _, pluginID := range pendingSources(mod, decodeDoc(sr.Document), sr.ID, idx, nowt) {
			tasks = append(tasks, queueTask{rowID: sr.ID, pluginID: pluginID})
		}
	}
	return tasks, nil
}

// pendingSources is the shared per-row derivation predicate: the plugin ids of
// the module's metadata chain that still have pending work for the row —
// queueable (D-Q1), namespace absent (not done), not in-ledger-cooldown. The
// SAME predicate runs over items and series rows; nothing here names a media
// type (INV-media-type-agnostic).
func pendingSources(mod module.Module, doc map[string]any, rowID string, idx failureIndex, nowt time.Time) []string {
	out := make([]string, 0)
	for _, src := range mod.MetadataSources {
		if !queueable(src) || hasNamespace(doc, src.PluginID) {
			continue
		}
		if inCooldown(idx, rowID, src.PluginID, nowt) {
			continue
		}
		out = append(out, src.PluginID)
	}
	return out
}

// allItems paginates QueryItems across ALL statuses (empty status = no filter)
// for a library, so the derivation predicate owns the status-set filter (pending,
// failed, stale, etc. all carry pending work and are naturally re-derived).
func (q *Queue) allItems(ctx context.Context, libraryID int64) ([]store.Item, error) {
	var out []store.Item
	for offset := 0; ; offset += deriveBatch {
		batch, err := q.deps.Store.QueryItems(ctx, libraryID, "", deriveBatch, offset)
		if err != nil {
			return nil, fmt.Errorf("enrich: derive items lib %d: %w", libraryID, err)
		}
		out = append(out, batch...)
		if len(batch) < deriveBatch {
			return out, nil
		}
	}
}

// allSeries loads a library's series rows across ALL statuses (empty status =
// no filter) — the second derivation source (serials-library D5). Series counts
// are small (one row per serial directory), so a single QuerySeries call is the
// intended granularity.
func (q *Queue) allSeries(ctx context.Context, libraryID int64) ([]store.Series, error) {
	rows, err := q.deps.Store.QuerySeries(ctx, libraryID, "")
	if err != nil {
		return nil, fmt.Errorf("enrich: derive series lib %d: %w", libraryID, err)
	}
	return rows, nil
}

// fetchFailureIndex reads the ledger once (terminal-only, small) for the
// cooldown-skip + prior-attempts lookups.
func (q *Queue) fetchFailureIndex(ctx context.Context) (failureIndex, error) {
	rows, err := q.deps.Store.ListFailures(ctx)
	if err != nil {
		return nil, fmt.Errorf("enrich: derive ledger: %w", err)
	}
	return buildFailureIndex(rows), nil
}

// queueable is the D-Q1 source predicate: Enabled and not CLIENT-only. Empty
// (tv-parser, local) and SERVER sources are server-runnable and therefore queued.
func queueable(src module.MetadataSourceBinding) bool {
	return src.Enabled && src.AuthMode != authModeClient
}

// hasNamespace reports whether the source already wrote its namespace (done).
func hasNamespace(doc map[string]any, pluginID string) bool {
	if len(doc) == 0 {
		return false
	}
	sources, ok := doc["sources"].(map[string]any)
	if !ok {
		return false
	}
	_, exists := sources[pluginID]
	return exists
}

// queueRow is one loaded queue target — an item OR a series row
// (serials-library D5). Document, lifecycle, lease, and ledger machinery are
// identical for both; only the persist sink differs (PutItem vs PutSeries).
type queueRow struct {
	id       string
	moduleID string
	status   string
	doc      json.RawMessage
	persist  func(ctx context.Context, status string, doc json.RawMessage)
}

// loadRow loads the queue target by row id: the item table first, the series
// table on sql.ErrNoRows — NO id-prefix sniffing (the prefixes are opaque,
// serials-library D5). A row missing from both tables is gone (deleted between
// derive and work) and yields an error the driver treats as nothing-to-do.
func (q *Queue) loadRow(ctx context.Context, id string) (queueRow, error) {
	it, err := q.deps.Store.GetItem(ctx, id)
	if err == nil {
		return queueRow{
			id: it.ID, moduleID: it.ModuleID, status: it.Status, doc: it.Document,
			persist: func(ctx context.Context, status string, doc json.RawMessage) {
				q.putItem(ctx, it, status, doc)
			},
		}, nil
	}
	if !errors.Is(err, sql.ErrNoRows) {
		return queueRow{}, err
	}
	sr, serr := q.deps.Store.GetSeries(ctx, id)
	if serr != nil {
		return queueRow{}, serr // includes ErrNoRows: the row is gone
	}
	return queueRow{
		id: sr.ID, moduleID: sr.ModuleID, status: sr.Status, doc: sr.Document,
		persist: func(ctx context.Context, status string, doc json.RawMessage) {
			q.putSeries(ctx, sr, status, doc)
		},
	}, nil
}

// workItem is the per-row worker driver: claim the row's lease, drive its
// pending queueable sources serially, advance the lifecycle, and persist. Soft-
// fail: a source failure / unavailable / namespace violation is recorded and the
// row advances to its furthest-valid state; only ctx.Done() hard-aborts (-> failed).
// Serialize-within-row: the lease blocks any second worker for this row (S4) —
// a series and its episodes never serialize against each other (distinct ids).
func (q *Queue) workItem(ctx context.Context, rowID string) {
	if !q.leases.acquire(rowID, "queue", q.cfg.LeaseTTL) {
		return // live lease held -> another worker owns this row
	}
	defer q.leases.release(rowID)
	done := make(chan struct{})
	defer close(done)
	go q.renewLease(rowID, q.cfg.LeaseTTL, done) // a live long run is never treated as dead mid-flight
	q.statPending.Add(-1)
	q.statInFlight.Add(1)
	defer q.statInFlight.Add(-1)

	row, err := q.loadRow(ctx, rowID)
	if err != nil {
		return // row gone (deleted) or unreadable; nothing to do
	}
	mod, err := q.deps.Modules.Get(row.moduleID)
	if err != nil {
		return // module unresolvable; leave the row as-is (soft)
	}
	idx, err := q.fetchFailureIndex(ctx)
	if err != nil {
		return
	}
	doc := decodeDoc(row.doc)
	status := reengage(row.status)
	dr := q.driveSources(ctx, mod, doc, reconstructBase(doc), rowID, idx, &status)
	if dr.hardAbort {
		q.hardFail(ctx, row, doc, dr.err)
		return
	}
	if dr.begun && dr.succeeded > 0 {
		status = advance(status, evEnriched) // parsed -> enriched
	}
	status = q.settle(ctx, mod, doc, rowID, status)
	q.persistRow(ctx, row, status, doc)
	if status == statusReady {
		q.statDone.Add(1)
	}
}

// reengage returns the in-flight status for an item entering the worker: failed
// re-enters pending (retry, exercised in B1); stale re-enters pending
// (rehydrate); every other status is unchanged (pending/new/parsed/enriched all
// carry pending work and drive their own advancement).
func reengage(status string) string {
	switch status {
	case statusFailed:
		return advance(status, evRetry)
	case statusStale:
		return advance(status, evRehydrate)
	}
	return status
}

// settle advances an enriched item to ready when none of its queueable sources
// has pending work left (all done or in-ledger-cooldown). The failure index is
// re-fetched here (not reused from workItem entry) because driveSources may have
// just written a terminal ledger row that makes a source terminal — a stale
// index would leave a fully-drained item stuck at enriched.
func (q *Queue) settle(ctx context.Context, mod module.Module, doc map[string]any, itemID string, status string) string {
	if status != statusEnriched {
		return status
	}
	idx, err := q.fetchFailureIndex(ctx)
	if err != nil {
		return status
	}
	if !allSourcesTerminal(idx, mod, doc, itemID, now()) {
		return status
	}
	return advance(status, evSettled) // enriched -> ready
}

// hardFail is the ctx-cancel path: stamp the _error record and persist status=
// failed (the queue re-derives the row's pending sources on a later pass,
// driving failed --retry--> pending). Mirrors enrich.go's hardError.
func (q *Queue) hardFail(ctx context.Context, row queueRow, doc map[string]any, cause error) {
	_ = hardError(doc, cause)
	q.persistRow(ctx, row, statusFailed, doc)
	q.statFailed.Add(1)
}

// persistRow writes the (possibly enriched) document + advanced status back via
// the row's persist sink (PutItem for items, PutSeries for series rows — both
// upserts refresh the existing row; the queue never creates rows).
func (q *Queue) persistRow(ctx context.Context, row queueRow, status string, doc map[string]any) {
	docBytes, err := json.Marshal(doc)
	if err != nil {
		return // a map of strings/maps never fails; keep the prior document on the impossible error
	}
	row.persist(ctx, status, docBytes)
}

// putItem is the item persist sink: refresh the loaded item's document + status.
func (q *Queue) putItem(ctx context.Context, it store.Item, status string, docBytes json.RawMessage) {
	it.Document = docBytes
	it.Status = status
	q.storeWrite(func() error { return q.deps.Store.PutItem(ctx, it) })
}

// putSeries is the series persist sink: refresh the loaded series row's
// document + status. PutSeries upserts by (library_id, relative_path), so the
// row's id and created_at survive (the store's upsert contract).
func (q *Queue) putSeries(ctx context.Context, sr store.Series, status string, docBytes json.RawMessage) {
	sr.Document = docBytes
	sr.Status = status
	q.storeWrite(func() error { return q.deps.Store.PutSeries(ctx, sr) })
}

// storeWrite serializes store writes. SQLite (modernc.org/sqlite) is opened by
// store.Open with WAL but no busy_timeout (default 0), so concurrent writers fail
// immediately with "database is locked" and a write would silently drop; the
// queue owns write serialization so a worker's terminal/advance write is durable.
// WAL lets reads stay concurrent with the single writer. A busy_timeout pragma
// in store.Open would be the more general fix — deferred to the store's scope.
func (q *Queue) storeWrite(fn func() error) {
	q.writeMu.Lock()
	defer q.writeMu.Unlock()
	_ = fn() // soft-fail: a failed write leaves the item re-derivable (existing pattern)
}
